// =============================================================================
// editor_avanzado_powerbi.m
// -----------------------------------------------------------------------------
// Qué es esto: el código en lenguaje M que queda registrado en el
// "Editor avanzado" de Power Query cuando usás Transformar -> Ejecutar
// script de Python. El Editor avanzado NUNCA ejecuta Python directamente:
// lo que hace es invocar la función Python.Execute(...) pasándole el
// código Python como texto, y a partir de ahí Power BI corre ese texto en
// tu instalación local de Python.
//
// CÓMO USAR ESTE ARCHIVO:
//   1. Abrí el Editor de Power Query -> clic derecho en la consulta que
//      querés limpiar -> "Editor avanzado".
//   2. Pegá este bloque completo, reemplazando el contenido existente
//      (o insertando el paso "EjecutarLimpieza" dentro de tu secuencia
//      de pasos ya existente, ANTES del "in" final).
//   3. Ajustá el nombre del paso anterior en la línea
//      "Origen = <tu paso anterior>" para que apunte al último paso de
//      limpieza/transformación que ya tenías (por ejemplo, el paso donde
//      quedó tu tabla ya con los tipos de datos básicos corregidos).
//   4. El texto Python que va entre comillas triples de M (#"...") es
//      exactamente el contenido de "limpiador_powerbi.py" (10 reglas:
//      faltante, duplicado, atipico, tipo_invalido, fecha_invalida,
//      email_invalido, telefono_invalido, id_duplicado,
//      formula_incorrecta, texto_inconsistente). Si cambiás las acciones
//      de limpieza en ese script, actualizá también este bloque (o
//      simplemente repetí el paso desde la interfaz gráfica: Transformar
//      -> Ejecutar script de Python, para que Power BI regenere este
//      fragmento automáticamente).
// =============================================================================

let
    // Reemplazá "TuPasoAnterior" por el nombre real del último paso de tu
    // consulta (el que entrega la tabla que querés corregir).
    Origen = TuPasoAnterior,

    EjecutarLimpieza = Python.Execute("import re#(lf)import difflib#(lf)import unicodedata#(lf)import pandas as pd#(lf)import numpy as np#(lf)#(lf)# -----------------------------------------------------------------------------#(lf)# CONFIGURACIÓN: ajustá según cómo querés corregir cada tipo de problema.#(lf)# Opciones válidas: 'eliminar_fila', 'reemplazar_media', 'reemplazar_mediana',#(lf)# 'reemplazar_moda', 'limitar', 'marcar_solo', 'valor_fijo', 'usar_sugerido'.#(lf)# ('limitar' solo aplica a ACCION_ATIPICO; 'reemplazar_media/mediana/moda'#(lf)# solo a faltante/tipo_invalido/atipico; 'usar_sugerido' solo a#(lf)# ACCION_FORMULA_INCORRECTA / ACCION_TEXTO_INCONSISTENTE, cuando el#(lf)# detector pudo calcular un valor correcto/canónico).#(lf)# -----------------------------------------------------------------------------#(lf)ACCION_FALTANTE = ""reemplazar_mediana""#(lf)ACCION_DUPLICADO = ""eliminar_fila""#(lf)ACCION_ATIPICO = ""limitar""#(lf)ACCION_TIPO_INVALIDO = ""marcar_solo""#(lf)FACTOR_IQR = 1.5#(lf)VALORES_FIJOS = {}   # ej: {""columna_x"": 0} si alguna acción es 'valor_fijo'#(lf)#(lf)# Las 6 reglas nuevas quedan en 'marcar_solo' por defecto: corregirlas#(lf)# automáticamente es riesgoso (un email o teléfono ""corregido"" a ciegas#(lf)# puede quedar mal). Cambiá cualquiera de estas 6 líneas si querés que se#(lf)# corrijan solas (por ejemplo a 'valor_fijo', 'eliminar_fila', o#(lf)# 'usar_sugerido' para las dos que traen un valor sugerido calculado).#(lf)ACCION_FECHA_INVALIDA = ""marcar_solo""#(lf)ACCION_EMAIL_INVALIDO = ""marcar_solo""#(lf)ACCION_TELEFONO_INVALIDO = ""marcar_solo""#(lf)ACCION_ID_DUPLICADO = ""marcar_solo""#(lf)ACCION_FORMULA_INCORRECTA = ""marcar_solo""#(lf)ACCION_TEXTO_INCONSISTENTE = ""marcar_solo""#(lf)#(lf)# Configuración fina de las 6 reglas nuevas. Dejá en None / True para#(lf)# auto-detectar columnas por nombre; completá explícitamente si tu tabla#(lf)# usa nombres de columna distintos a los patrones habituales.#(lf)AUTO_DETECTAR_COLUMNAS = True#(lf)COLUMNAS_FECHA = None          # ej: [""fecha_venta""]#(lf)FECHA_MIN = None               # ej: ""2023-01-01""#(lf)FECHA_MAX = None               # ej: ""2026-12-31""#(lf)COLUMNAS_EMAIL = None          # ej: [""correo_cliente""]#(lf)COLUMNAS_TELEFONO = None       # ej: [""telefono_cliente""]#(lf)PATRON_TELEFONO = None         # regex propio si el formato no es CR estándar#(lf)DIGITOS_TELEFONO = (8, 8)      # (min, max) dígitos esperados#(lf)COLUMNAS_ID = None             # ej: [""id_producto""]#(lf)COLUMNA_TOTAL = None           # ej: ""total""#(lf)COLUMNA_CANTIDAD = None        # ej: ""cantidad""#(lf)COLUMNA_PRECIO = None          # ej: ""precio_unitario""#(lf)TOLERANCIA_FORMULA = 0.01      # 1% relativo, con piso absoluto de 0.01#(lf)COLUMNAS_TEXTO = None          # ej: [""categoria"", ""metodo_pago""]#(lf)UMBRAL_SIMILITUD_TEXTO = 0.85#(lf)MAX_CARDINALIDAD_RATIO_TEXTO = 0.5#(lf)#(lf)ACCIONES_VALIDAS = {#(lf)    ""eliminar_fila"", ""reemplazar_media"", ""reemplazar_mediana"",#(lf)    ""reemplazar_moda"", ""limitar"", ""marcar_solo"", ""valor_fijo"", ""usar_sugerido"",#(lf)}#(lf)_TIPOS_VALOR_FIJO_DIRECTO = {#(lf)    ""fecha_invalida"", ""email_invalido"", ""telefono_invalido"",#(lf)    ""id_duplicado"", ""formula_incorrecta"", ""texto_inconsistente"",#(lf)}#(lf)_TIPOS_CON_SUGERENCIA = {""formula_incorrecta"", ""texto_inconsistente""}#(lf)#(lf)_REGEX_EMAIL = re.compile(r""^[^@\s]+@[^@\s]+\.[^@\s]{2,}$"")#(lf)_REGEX_TELEFONO_FORMATO = re.compile(r""^[\d\s\-\+\(\)]+$"")#(lf)#(lf)_PATRONES_EMAIL = (""email"", ""correo"", ""e-mail"", ""mail"")#(lf)_PATRONES_TELEFONO = (""telefono"", ""teléfono"", ""phone"", ""celular"", ""movil"", ""móvil"", ""whatsapp"")#(lf)_PATRONES_FECHA = (""fecha"", ""date"")#(lf)_PATRONES_TOTAL = (""total"",)#(lf)_PATRONES_CANTIDAD = (""cantidad"", ""qty"", ""cant_"")#(lf)_PATRONES_PRECIO = (""precio"", ""price"")#(lf)_PATRONES_EXCLUIR_TEXTO = _PATRONES_EMAIL + _PATRONES_TELEFONO + _PATRONES_FECHA + \#(lf)    (""nombre"", ""cliente"", ""direccion"", ""dirección"", ""observacion"", ""observación"", ""comentario"")#(lf)#(lf)#(lf)def _columna_numerica_potencial(serie):#(lf)    valores = serie.dropna()#(lf)    if len(valores) == 0:#(lf)        return False#(lf)    convertibles = pd.to_numeric(valores, errors=""coerce"")#(lf)    return convertibles.notna().mean() > 0.7#(lf)#(lf)#(lf)def _columnas_para_atipicos(df):#(lf)    columnas = df.select_dtypes(include=[np.number]).columns.tolist()#(lf)    for col in df.columns:#(lf)        if col in columnas:#(lf)            continue#(lf)        serie = df[col]#(lf)        if (pd.api.types.is_object_dtype(serie) or pd.api.types.is_string_dtype(serie)) \#(lf)                and _columna_numerica_potencial(serie):#(lf)            columnas.append(col)#(lf)    return columnas#(lf)#(lf)#(lf)def _columnas_por_patron(df, patrones):#(lf)    return [col for col in df.columns if any(p in str(col).lower() for p in patrones)]#(lf)#(lf)#(lf)def _es_columna_id(col):#(lf)    low = str(col).lower()#(lf)    if low == ""id"":#(lf)        return True#(lf)    if low.startswith(""id_"") or low.endswith(""_id"") or ""_id_"" in low:#(lf)        return True#(lf)    if any(p in low for p in (""codigo"", ""código"", ""folio"")):#(lf)        return True#(lf)    return False#(lf)#(lf)#(lf)def _normalizar_texto(valor):#(lf)    s = str(valor).strip().lower()#(lf)    s = """".join(c for c in unicodedata.normalize(""NFKD"", s) if not unicodedata.combining(c))#(lf)    return "" "".join(s.split())#(lf)#(lf)#(lf)def _detectar_hallazgos_originales(df, factor_iqr=1.5):#(lf)    hallazgos = []#(lf)#(lf)    for col in df.columns:#(lf)        for idx in df[df[col].isna()].index:#(lf)            hallazgos.append({""tipo"": ""faltante"", ""columna"": col, ""fila"": int(idx),#(lf)                               ""valor_original"": None, ""detalle"": ""Valor vacío/nulo"",#(lf)                               ""valor_sugerido"": None})#(lf)#(lf)    mask_dup = df.duplicated(keep=""first"")#(lf)    for idx in df[mask_dup].index:#(lf)        hallazgos.append({""tipo"": ""duplicado"", ""columna"": None, ""fila"": int(idx),#(lf)                           ""valor_original"": df.loc[idx].to_dict(),#(lf)                           ""detalle"": ""Fila duplicada (idéntica a una anterior)"",#(lf)                           ""valor_sugerido"": None})#(lf)#(lf)    for col in df.columns:#(lf)        serie = df[col]#(lf)        es_texto = pd.api.types.is_object_dtype(serie) or pd.api.types.is_string_dtype(serie)#(lf)        if es_texto and _columna_numerica_potencial(serie):#(lf)            convertidos = pd.to_numeric(serie, errors=""coerce"")#(lf)            malos = serie[(convertidos.isna()) & (serie.notna())]#(lf)            for idx, val in malos.items():#(lf)                hallazgos.append({""tipo"": ""tipo_invalido"", ""columna"": col, ""fila"": int(idx),#(lf)                                   ""valor_original"": val, ""detalle"": ""Se esperaba un valor numérico"",#(lf)                                   ""valor_sugerido"": None})#(lf)#(lf)    for col in _columnas_para_atipicos(df):#(lf)        serie = pd.to_numeric(df[col], errors=""coerce"")#(lf)        q1, q3 = serie.quantile(0.25), serie.quantile(0.75)#(lf)        iqr = q3 - q1#(lf)        if iqr == 0 or pd.isna(iqr):#(lf)            continue#(lf)        lim_inf, lim_sup = q1 - factor_iqr * iqr, q3 + factor_iqr * iqr#(lf)        atipicos = serie[(serie < lim_inf) | (serie > lim_sup)]#(lf)        for idx, val in atipicos.items():#(lf)            hallazgos.append({""tipo"": ""atipico"", ""columna"": col, ""fila"": int(idx),#(lf)                               ""valor_original"": val,#(lf)                               ""detalle"": f""Fuera de rango [{lim_inf:.2f}, {lim_sup:.2f}] (IQR)"",#(lf)                               ""valor_sugerido"": None})#(lf)#(lf)    return hallazgos#(lf)#(lf)#(lf)def _detectar_fechas_invalidas(df, columnas, fecha_min, fecha_max, auto):#(lf)    hallazgos = []#(lf)    cols = columnas if columnas is not None else (_columnas_por_patron(df, _PATRONES_FECHA) if auto else [])#(lf)    lim_min = pd.Timestamp(fecha_min) if fecha_min is not None else None#(lf)    lim_max = pd.Timestamp(fecha_max) if fecha_max is not None else None#(lf)    for col in cols:#(lf)        if col not in df.columns:#(lf)            continue#(lf)        serie = df[col]#(lf)        parseado = pd.to_datetime(serie, errors=""coerce"")#(lf)        for idx, val in serie.items():#(lf)            if pd.isna(val):#(lf)                continue#(lf)            fecha = parseado.loc[idx]#(lf)            if pd.isna(fecha):#(lf)                fecha = pd.to_datetime(val, errors=""coerce"", dayfirst=True)#(lf)            if pd.isna(fecha):#(lf)                hallazgos.append({""tipo"": ""fecha_invalida"", ""columna"": col, ""fila"": int(idx),#(lf)                                   ""valor_original"": val, ""detalle"": ""Formato de fecha no reconocido"",#(lf)                                   ""valor_sugerido"": None})#(lf)                continue#(lf)            if lim_min is not None and fecha < lim_min:#(lf)                hallazgos.append({""tipo"": ""fecha_invalida"", ""columna"": col, ""fila"": int(idx),#(lf)                                   ""valor_original"": val,#(lf)                                   ""detalle"": f""Fecha fuera de rango (anterior a {lim_min.date()})"",#(lf)                                   ""valor_sugerido"": None})#(lf)            elif lim_max is not None and fecha > lim_max:#(lf)                hallazgos.append({""tipo"": ""fecha_invalida"", ""columna"": col, ""fila"": int(idx),#(lf)                                   ""valor_original"": val,#(lf)                                   ""detalle"": f""Fecha fuera de rango (posterior a {lim_max.date()})"",#(lf)                                   ""valor_sugerido"": None})#(lf)    return hallazgos#(lf)#(lf)#(lf)def _detectar_emails_invalidos(df, columnas, auto):#(lf)    hallazgos = []#(lf)    cols = columnas if columnas is not None else (_columnas_por_patron(df, _PATRONES_EMAIL) if auto else [])#(lf)    for col in cols:#(lf)        if col not in df.columns:#(lf)            continue#(lf)        for idx, val in df[col].items():#(lf)            if pd.isna(val):#(lf)                continue#(lf)            if not _REGEX_EMAIL.match(str(val).strip()):#(lf)                hallazgos.append({""tipo"": ""email_invalido"", ""columna"": col, ""fila"": int(idx),#(lf)                                   ""valor_original"": val, ""detalle"": ""Formato de correo electrónico inválido"",#(lf)                                   ""valor_sugerido"": None})#(lf)    return hallazgos#(lf)#(lf)#(lf)def _detectar_telefonos_invalidos(df, columnas, patron, min_digitos, max_digitos, auto):#(lf)    hallazgos = []#(lf)    cols = columnas if columnas is not None else (_columnas_por_patron(df, _PATRONES_TELEFONO) if auto else [])#(lf)    regex_formato = re.compile(patron) if patron else _REGEX_TELEFONO_FORMATO#(lf)    for col in cols:#(lf)        if col not in df.columns:#(lf)            continue#(lf)        for idx, val in df[col].items():#(lf)            if pd.isna(val):#(lf)                continue#(lf)            texto = str(val).strip()#(lf)            solo_digitos = re.sub(r""\D"", """", texto)#(lf)            formato_ok = bool(regex_formato.match(texto))#(lf)            longitud_ok = min_digitos <= len(solo_digitos) <= max_digitos#(lf)            if not (formato_ok and longitud_ok):#(lf)                rango = f""{min_digitos}"" if min_digitos == max_digitos else f""{min_digitos}-{max_digitos}""#(lf)                hallazgos.append({""tipo"": ""telefono_invalido"", ""columna"": col, ""fila"": int(idx),#(lf)                                   ""valor_original"": val,#(lf)                                   ""detalle"": f""Formato/longitud de teléfono inválido (se esperaban {rango} dígitos)"",#(lf)                                   ""valor_sugerido"": None})#(lf)    return hallazgos#(lf)#(lf)#(lf)def _detectar_ids_duplicados(df, columnas, auto):#(lf)    cols = columnas if columnas is not None else ([c for c in df.columns if _es_columna_id(c)] if auto else [])#(lf)    hallazgos = []#(lf)    for col in cols:#(lf)        if col not in df.columns:#(lf)            continue#(lf)        serie = df[col]#(lf)        mask = serie.duplicated(keep=""first"") & serie.notna()#(lf)        for idx in serie[mask].index:#(lf)            hallazgos.append({""tipo"": ""id_duplicado"", ""columna"": col, ""fila"": int(idx),#(lf)                               ""valor_original"": serie.loc[idx],#(lf)                               ""detalle"": f""Valor repetido en columna identificadora '{col}' ""#(lf)                                          ""(la fila completa no es idéntica)"",#(lf)                               ""valor_sugerido"": None})#(lf)    return hallazgos#(lf)#(lf)#(lf)def _detectar_formula_incorrecta(df, columna_total, columna_cantidad, columna_precio, tolerancia, auto):#(lf)    hallazgos = []#(lf)    if auto and not (columna_total and columna_cantidad and columna_precio):#(lf)        cand_total = _columnas_por_patron(df, _PATRONES_TOTAL)#(lf)        cand_cant = _columnas_por_patron(df, _PATRONES_CANTIDAD)#(lf)        cand_precio = _columnas_por_patron(df, _PATRONES_PRECIO)#(lf)        if cand_total and cand_cant and cand_precio:#(lf)            columna_total = columna_total or cand_total[0]#(lf)            columna_cantidad = columna_cantidad or cand_cant[0]#(lf)            columna_precio = columna_precio or cand_precio[0]#(lf)#(lf)    if not (columna_total and columna_cantidad and columna_precio):#(lf)        return hallazgos#(lf)    if not all(c in df.columns for c in (columna_total, columna_cantidad, columna_precio)):#(lf)        return hallazgos#(lf)#(lf)    total = pd.to_numeric(df[columna_total], errors=""coerce"")#(lf)    cantidad = pd.to_numeric(df[columna_cantidad], errors=""coerce"")#(lf)    precio = pd.to_numeric(df[columna_precio], errors=""coerce"")#(lf)    esperado = cantidad * precio#(lf)    diferencia = (total - esperado).abs()#(lf)    limite = (esperado.abs() * tolerancia).clip(lower=0.01)#(lf)    mal = (diferencia > limite) & total.notna() & esperado.notna()#(lf)#(lf)    for idx in df[mal].index:#(lf)        valor_correcto = esperado.loc[idx]#(lf)        hallazgos.append({""tipo"": ""formula_incorrecta"", ""columna"": columna_total, ""fila"": int(idx),#(lf)                           ""valor_original"": df.loc[idx, columna_total],#(lf)                           ""detalle"": f""{columna_total} no coincide con {columna_cantidad} × {columna_precio} ""#(lf)                                      f""(esperado ≈ {valor_correcto:.2f})"",#(lf)                           ""valor_sugerido"": round(float(valor_correcto), 2) if pd.notna(valor_correcto) else None})#(lf)    return hallazgos#(lf)#(lf)#(lf)def _detectar_texto_inconsistente(df, columnas, auto, umbral_similitud, max_cardinalidad_ratio,#(lf)                                   min_apariciones_canonica=1):#(lf)    if columnas is not None:#(lf)        cols = columnas#(lf)    elif auto:#(lf)        cols = []#(lf)        for col in df.columns:#(lf)            serie = df[col]#(lf)            es_texto = pd.api.types.is_object_dtype(serie) or pd.api.types.is_string_dtype(serie)#(lf)            if not es_texto or _es_columna_id(col):#(lf)                continue#(lf)            if any(p in str(col).lower() for p in _PATRONES_EXCLUIR_TEXTO):#(lf)                continue#(lf)            no_nulos = serie.dropna()#(lf)            if len(no_nulos) == 0:#(lf)                continue#(lf)            ratio = no_nulos.map(_normalizar_texto).nunique() / len(no_nulos)#(lf)            if ratio <= max_cardinalidad_ratio:#(lf)                cols.append(col)#(lf)    else:#(lf)        cols = []#(lf)#(lf)    hallazgos = []#(lf)    for col in cols:#(lf)        if col not in df.columns:#(lf)            continue#(lf)        serie = df[col].dropna()#(lf)        if serie.empty:#(lf)            continue#(lf)#(lf)        conteo_por_texto = serie.astype(str).value_counts()#(lf)        textos_por_norm = {}#(lf)        for texto, cuenta in conteo_por_texto.items():#(lf)            norm = _normalizar_texto(texto)#(lf)            textos_por_norm.setdefault(norm, []).append((texto, int(cuenta)))#(lf)#(lf)        normalizados = list(textos_por_norm.keys())#(lf)        visitados = set()#(lf)        grupos = []#(lf)        for i, n1 in enumerate(normalizados):#(lf)            if n1 in visitados:#(lf)                continue#(lf)            grupo = [n1]#(lf)            visitados.add(n1)#(lf)            for n2 in normalizados[i + 1:]:#(lf)                if n2 in visitados:#(lf)                    continue#(lf)                if difflib.SequenceMatcher(None, n1, n2).ratio() >= umbral_similitud:#(lf)                    grupo.append(n2)#(lf)                    visitados.add(n2)#(lf)            grupos.append(grupo)#(lf)#(lf)        for grupo in grupos:#(lf)            candidatas = [par for n in grupo for par in textos_por_norm[n]]#(lf)            if len(candidatas) < 2:#(lf)                continue#(lf)            canonica_texto, canonica_cuenta = max(candidatas, key=lambda t: t[1])#(lf)            if canonica_cuenta < min_apariciones_canonica:#(lf)                continue#(lf)            for texto_variante, _ in candidatas:#(lf)                if texto_variante == canonica_texto:#(lf)                    continue#(lf)                for idx, val in serie.items():#(lf)                    if str(val) == texto_variante:#(lf)                        hallazgos.append({""tipo"": ""texto_inconsistente"", ""columna"": col, ""fila"": int(idx),#(lf)                                           ""valor_original"": val,#(lf)                                           ""detalle"": f""Posible variante/error de tipeo de '{canonica_texto}'"",#(lf)                                           ""valor_sugerido"": canonica_texto})#(lf)    return hallazgos#(lf)#(lf)#(lf)def _asignar(df, fila, columna, valor):#(lf)    try:#(lf)        df.at[fila, columna] = valor#(lf)    except (TypeError, ValueError):#(lf)        df[columna] = df[columna].astype(object)#(lf)        df.at[fila, columna] = valor#(lf)#(lf)#(lf)def _valor_reemplazo(df, columna, accion, valor_fijo=None):#(lf)    serie_num = pd.to_numeric(df[columna], errors=""coerce"")#(lf)    if accion == ""reemplazar_media"":#(lf)        return serie_num.mean()#(lf)    if accion == ""reemplazar_mediana"":#(lf)        return serie_num.median()#(lf)    if accion == ""reemplazar_moda"":#(lf)        moda = df[columna].mode(dropna=True)#(lf)        return moda.iloc[0] if not moda.empty else None#(lf)    if accion == ""valor_fijo"":#(lf)        return valor_fijo#(lf)    return None#(lf)#(lf)#(lf)def limpiar_tabla(df, faltante, duplicado, atipico, tipo_invalido, factor_iqr, valores_fijos,#(lf)                   fecha_invalida, email_invalido, telefono_invalido, id_duplicado,#(lf)                   formula_incorrecta, texto_inconsistente,#(lf)                   auto_detectar_columnas, columnas_fecha, fecha_min, fecha_max,#(lf)                   columnas_email, columnas_telefono, patron_telefono, digitos_telefono,#(lf)                   columnas_id, columna_total, columna_cantidad, columna_precio, tolerancia_formula,#(lf)                   columnas_texto, umbral_similitud_texto, max_cardinalidad_ratio_texto):#(lf)    config = {#(lf)        ""faltante"": faltante, ""duplicado"": duplicado, ""atipico"": atipico, ""tipo_invalido"": tipo_invalido,#(lf)        ""fecha_invalida"": fecha_invalida, ""email_invalido"": email_invalido,#(lf)        ""telefono_invalido"": telefono_invalido, ""id_duplicado"": id_duplicado,#(lf)        ""formula_incorrecta"": formula_incorrecta, ""texto_inconsistente"": texto_inconsistente,#(lf)    }#(lf)    for tipo, accion in config.items():#(lf)        if accion not in ACCIONES_VALIDAS:#(lf)            raise ValueError(f""Acción no válida para '{tipo}': '{accion}'. Use una de: {sorted(ACCIONES_VALIDAS)}"")#(lf)#(lf)    df_limpio = df.copy()#(lf)#(lf)    hallazgos = _detectar_hallazgos_originales(df, factor_iqr=factor_iqr)#(lf)    hallazgos += _detectar_fechas_invalidas(df, columnas_fecha, fecha_min, fecha_max, auto_detectar_columnas)#(lf)    hallazgos += _detectar_emails_invalidos(df, columnas_email, auto_detectar_columnas)#(lf)    hallazgos += _detectar_telefonos_invalidos(df, columnas_telefono, patron_telefono,#(lf)                                                digitos_telefono[0], digitos_telefono[1], auto_detectar_columnas)#(lf)    hallazgos += _detectar_ids_duplicados(df, columnas_id, auto_detectar_columnas)#(lf)    hallazgos += _detectar_formula_incorrecta(df, columna_total, columna_cantidad, columna_precio,#(lf)                                               tolerancia_formula, auto_detectar_columnas)#(lf)    hallazgos += _detectar_texto_inconsistente(df, columnas_texto, auto_detectar_columnas,#(lf)                                                umbral_similitud_texto, max_cardinalidad_ratio_texto)#(lf)#(lf)    limites_iqr = {}#(lf)    for h in hallazgos:#(lf)        if h[""tipo""] == ""atipico"" and h[""columna""] not in limites_iqr:#(lf)            serie = pd.to_numeric(df[h[""columna""]], errors=""coerce"")#(lf)            q1, q3 = serie.quantile(0.25), serie.quantile(0.75)#(lf)            iqr = q3 - q1#(lf)            limites_iqr[h[""columna""]] = (q1 - factor_iqr * iqr, q3 + factor_iqr * iqr)#(lf)#(lf)    registro = []#(lf)    filas_a_eliminar = set()#(lf)#(lf)    for h in hallazgos:#(lf)        accion = config.get(h[""tipo""], ""marcar_solo"")#(lf)        valor_nuevo = h[""valor_original""]#(lf)#(lf)        if accion == ""marcar_solo"":#(lf)            pass#(lf)        elif accion == ""eliminar_fila"":#(lf)            filas_a_eliminar.add(h[""fila""])#(lf)            valor_nuevo = ""(fila eliminada)""#(lf)        elif h[""tipo""] in (""faltante"", ""tipo_invalido"") and accion in (#(lf)                ""reemplazar_media"", ""reemplazar_mediana"", ""reemplazar_moda"", ""valor_fijo""):#(lf)            valor_nuevo = _valor_reemplazo(df, h[""columna""], accion, valores_fijos.get(h[""columna""]))#(lf)            _asignar(df_limpio, h[""fila""], h[""columna""], valor_nuevo)#(lf)        elif h[""tipo""] == ""atipico"" and accion == ""limitar"":#(lf)            lim_inf, lim_sup = limites_iqr.get(h[""columna""], (None, None))#(lf)            val_num = pd.to_numeric(pd.Series([h[""valor_original""]]), errors=""coerce"")[0]#(lf)            if lim_inf is not None and not pd.isna(val_num):#(lf)                valor_nuevo = lim_inf if val_num < lim_inf else lim_sup#(lf)                _asignar(df_limpio, h[""fila""], h[""columna""], valor_nuevo)#(lf)        elif h[""tipo""] == ""atipico"" and accion in (#(lf)                ""reemplazar_media"", ""reemplazar_mediana"", ""reemplazar_moda""):#(lf)            valor_nuevo = _valor_reemplazo(df, h[""columna""], accion)#(lf)            _asignar(df_limpio, h[""fila""], h[""columna""], valor_nuevo)#(lf)        elif h[""tipo""] in _TIPOS_CON_SUGERENCIA and accion == ""usar_sugerido"" \#(lf)                and h.get(""valor_sugerido"") is not None:#(lf)            valor_nuevo = h[""valor_sugerido""]#(lf)            _asignar(df_limpio, h[""fila""], h[""columna""], valor_nuevo)#(lf)        elif h[""tipo""] in _TIPOS_VALOR_FIJO_DIRECTO and accion == ""valor_fijo"":#(lf)            valor_nuevo = valores_fijos.get(h[""columna""])#(lf)            _asignar(df_limpio, h[""fila""], h[""columna""], valor_nuevo)#(lf)#(lf)        registro.append({#(lf)            ""tipo"": h[""tipo""],#(lf)            ""columna"": h[""columna""] or ""(fila completa)"",#(lf)            ""fila"": h[""fila""],#(lf)            ""valor_original"": str(h[""valor_original""]),#(lf)            ""accion_aplicada"": accion,#(lf)            ""valor_nuevo"": str(valor_nuevo),#(lf)            ""detalle"": h[""detalle""],#(lf)        })#(lf)#(lf)    marcas = {}#(lf)    for r in registro:#(lf)        if r[""accion_aplicada""] != ""marcar_solo"":#(lf)            continue#(lf)        etiqueta = r[""tipo""] if r[""columna""] == ""(fila completa)"" else f""{r['tipo']}:{r['columna']}""#(lf)        marcas.setdefault(r[""fila""], []).append(etiqueta)#(lf)#(lf)    if marcas:#(lf)        col_marca = ""_revisar_calidad""#(lf)        while col_marca in df_limpio.columns:#(lf)            col_marca += ""_""#(lf)        df_limpio[col_marca] = """"#(lf)        for fila, etiquetas in marcas.items():#(lf)            if fila in df_limpio.index:#(lf)                df_limpio.at[fila, col_marca] = ""; "".join(etiquetas)#(lf)#(lf)    if filas_a_eliminar:#(lf)        df_limpio = df_limpio.drop(index=list(filas_a_eliminar), errors=""ignore"").reset_index(drop=True)#(lf)#(lf)    df_reporte = pd.DataFrame(registro) if registro else pd.DataFrame(#(lf)        columns=[""tipo"", ""columna"", ""fila"", ""valor_original"", ""accion_aplicada"", ""valor_nuevo"", ""detalle""]#(lf)    )#(lf)    return df_limpio, df_reporte#(lf)#(lf)#(lf)# -----------------------------------------------------------------------------#(lf)# PUNTO DE ENTRADA que Power BI ejecuta automáticamente.#(lf)# ""dataset"" ya viene definido por Power Query con la tabla seleccionada.#(lf)# Las variables de salida que terminan siendo pandas DataFrame son las que#(lf)# Power BI ofrece como tablas para expandir en el panel de resultados.#(lf)# -----------------------------------------------------------------------------#(lf)dataset_limpio, reporte_limpieza = limpiar_tabla(#(lf)    dataset,#(lf)    faltante=ACCION_FALTANTE,#(lf)    duplicado=ACCION_DUPLICADO,#(lf)    atipico=ACCION_ATIPICO,#(lf)    tipo_invalido=ACCION_TIPO_INVALIDO,#(lf)    factor_iqr=FACTOR_IQR,#(lf)    valores_fijos=VALORES_FIJOS,#(lf)    fecha_invalida=ACCION_FECHA_INVALIDA,#(lf)    email_invalido=ACCION_EMAIL_INVALIDO,#(lf)    telefono_invalido=ACCION_TELEFONO_INVALIDO,#(lf)    id_duplicado=ACCION_ID_DUPLICADO,#(lf)    formula_incorrecta=ACCION_FORMULA_INCORRECTA,#(lf)    texto_inconsistente=ACCION_TEXTO_INCONSISTENTE,#(lf)    auto_detectar_columnas=AUTO_DETECTAR_COLUMNAS,#(lf)    columnas_fecha=COLUMNAS_FECHA, fecha_min=FECHA_MIN, fecha_max=FECHA_MAX,#(lf)    columnas_email=COLUMNAS_EMAIL,#(lf)    columnas_telefono=COLUMNAS_TELEFONO, patron_telefono=PATRON_TELEFONO,#(lf)    digitos_telefono=DIGITOS_TELEFONO,#(lf)    columnas_id=COLUMNAS_ID,#(lf)    columna_total=COLUMNA_TOTAL, columna_cantidad=COLUMNA_CANTIDAD, columna_precio=COLUMNA_PRECIO,#(lf)    tolerancia_formula=TOLERANCIA_FORMULA,#(lf)    columnas_texto=COLUMNAS_TEXTO, umbral_similitud_texto=UMBRAL_SIMILITUD_TEXTO,#(lf)    max_cardinalidad_ratio_texto=MAX_CARDINALIDAD_RATIO_TEXTO,#(lf))#(lf)", [dataset=Origen]),

